Here is a JavaScript function to debounce another function.

Debouncing is a technique used to limit the rate at which a function gets called. It ensures that the function is only executed after a certain amount of time has passed *since the last time it was invoked*. This is very useful for handling events like resizing, scrolling, or rapid keystrokes in a search bar.

### The Debounce Function

```javascript
/**
 * Creates a debounced version of a function that delays invoking `func`
 * until after `wait` milliseconds have elapsed since the last time the
 * debounced function was invoked.
 *
 * @param {Function} func The function to debounce.
 * @param {number} wait The number of milliseconds to wait after the last call.
 * @returns {Function} Returns the new debounced function.
 */
function debounce(func, wait) {
    let timeoutId;

    /**
     * The debounced function that will be called repeatedly.
     * @param {...any} args Arguments passed to the original function.
     */
    return function(...args) {
        // 'this' context is preserved for the original function call
        const context = this;

        // Clear the previous timeout if it exists
        clearTimeout(timeoutId);

        // Set a new timeout
        timeoutId = setTimeout(() => {
            // Execute the original function with the correct context and arguments
            func.apply(context, args);
        }, wait);
    };
}

// --- Example Usage ---

// 1. The function we want to debounce (e.g., an expensive API call or DOM manipulation)
function handleSearchInput(event) {
    console.log(`Searching for: ${event.target.value}`);
}

// 2. Create the debounced version, waiting 500ms
const debouncedSearch = debounce(handleSearchInput, 500);

// 3. Simulate rapid user input events
console.log("Simulating rapid typing...");

// Call 1 (will be cancelled)
debouncedSearch({ target: { value: 'a' } });

// Call 2 (will be cancelled)
setTimeout(() => {
    debouncedSearch({ target: { value: 'ap' } });
}, 100);

// Call 3 (will be cancelled)
setTimeout(() => {
    debouncedSearch({ target: { value: 'app' } });
}, 200);

// Call 4 (this one will eventually execute after 500ms of silence)
setTimeout(() => {
    debouncedSearch({ target: { value: 'apple' } });
}, 400);

// After a pause of 500ms following the last call, you will see:
// Searching for: apple
```

