Here is a well-structured JavaScript function that implements a **throttling** mechanism for another function.

Throttling ensures that a function is executed at most once every specified time interval.

```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
    let timeout = null;
    let lastArgs = null;
    let lastThis = null;
    let lastExecTime = 0;

    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if enough time has passed since the last execution
        if (now - lastExecTime >= wait) {
            // Execute immediately
            lastExecTime = now;
            func.apply(context, args);
        } else {
            // If not enough time has passed, store the latest arguments
            // to be executed after the wait period.
            lastArgs = args;
            lastThis = context;

            // If there is no pending timeout, set one to execute the function
            // after the wait period. This handles the "trailing edge" execution.
            if (!timeout) {
                timeout = setTimeout(() => {
                    lastExecTime = Date.now();
                    timeout = null;
                    // Execute with the last stored arguments and context
                    func.apply(lastThis, lastArgs);
                    lastArgs = null;
                    lastThis = null;
                }, wait - (now - lastExecTime)); // Calculate remaining time for accuracy
            }
        }
    };
}

// --- Example Usage ---

// 1. The function we want to throttle (e.g., an expensive API call or UI update)
function logActivity(message) {
    const timestamp = new Date().toLocaleTimeString();
    console.log(`[${timestamp}] Activity logged: ${message}`);
}

// 2. Create the throttled version, limiting execution to once every 1000ms (1 second)
const throttledLog = throttle(logActivity, 1000);

console.log("Starting rapid calls...");

