/**
 * Computes the median of an array of numbers.
 *
 * @param numbers An array of numbers.
 * @returns The median of the array, or null if the array is empty.
 */
function findMedian(numbers: number[]): number | null {
    if (numbers.length === 0) {
        return null;
    }

    // 1. Sort the array numerically
    const sortedNumbers: number[] = [...numbers].sort((a, b) => a - b);

    const length = sortedNumbers.length;

    // 2. Check if the length is odd or even
    if (length % 2 === 1) {
        // Odd length: the median is the middle element
        const middleIndex = Math.floor(length / 2);
        return sortedNumbers[middleIndex];
    } else {
        // Even length: the median is the average of the two middle elements
        const upperMiddleIndex = length / 2;
        const lowerMiddleIndex = upperMiddleIndex - 1;

        const middle1 = sortedNumbers[lowerMiddleIndex];
        const middle2 = sortedNumbers[upperMiddleIndex];

        return (middle1 + middle2) / 2;
    }
}

