Here is a TypeScript function that sums the values of an object.

Since objects can have different types of values (numbers, strings, etc.), this function will be designed to **only sum the values that are actually numbers**.

```typescript
/**
 * Type definition for an object where values can be of various types.
 */
interface NumericObject {
  [key: string]: number | string | number[] | any;
}

/**
 * Calculates the sum of all numeric values found within an object.
 * Non-numeric values (like strings or arrays) are ignored.
 *
 * @param obj The object whose values are to be summed.
 * @returns The total sum of the numeric values in the object.
 */
function sumObjectValues(obj: NumericObject): number {
  let sum: number = 0;

  // Iterate over the keys of the object
  for (const key in obj) {
    // Ensure the property belongs to the object itself and not its prototype chain
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];

      // Check if the value is a finite number before adding it to the sum
      if (typeof value === 'number' && isFinite(value)) {
        sum += value;
      }
    }
  }

  return sum;
}

// --- Example Usage ---

