/**
 * Copies a source string to a destination buffer without using strcpy.
 *
 * @param dest The destination buffer where the string will be copied.
 * @param src The source string to be copied.
 * @param dest_size The maximum size of the destination buffer (including the null terminator).
 * @return A pointer to the destination buffer.
 */
char* str_copy_strncpy(char* dest, const char* src, size_t dest_size) {
    if (dest == NULL || src == NULL) {
        return NULL;
    }

    // Copy at most (dest_size - 1) characters to leave space for the null terminator.
    strncpy(dest, src, dest_size - 1);

    // Manually ensure null termination, which strncpy might not do if src is too long.
    dest[dest_size - 1] = '\0';

    return dest;
}

