/// The sequence starts with F(0) = 0 and F(1) = 1.
///
/// # Arguments
///
/// * `n` - The index of the Fibonacci number to calculate (n >= 0).
///
/// # Returns
///
/// The n-th Fibonacci number as a u64. Returns 0 if n is negative.
pub fn fibonacci_iterative(n: u32) -> u64 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }

    let mut a: u64 = 0;
    let mut b: u64 = 1;
    let mut result: u64 = 0;

    // Start loop from the 2nd number up to n
    for _ in 2..=n {
        result = a.checked_add(b).expect("Fibonacci number overflowed u64");
        a = b;
        b = result;
    }

    result
}

fn main() {
    println!("Fib(0): {}", fibonacci_iterative(0)); // 0
    println!("Fib(1): {}", fibonacci_iterative(1)); // 1
    println!("Fib(2): {}", fibonacci_iterative(2)); // 1
    println!("Fib(10): {}", fibonacci_iterative(10)); // 55
    println!("Fib(50): {}", fibonacci_iterative(50)); // 12586269025 (This will overflow u64!)
}
```

**Note on Overflow:** The `u64` type can only hold Fibonacci numbers up to $F_{93}$. If you need larger numbers, you should use a Big Integer library like `num-bigint`.

