/// Finds the largest element in a slice of i32.
///
/// Returns `None` if the slice is empty.
///
/// # Arguments
///
/// * `slice` - A slice of i32 to search through.
///
/// # Returns
///
/// An `Option<i32>` containing the largest element, or `None` if the slice is empty.
fn find_largest(slice: &[i32]) -> Option<i32> {
    if slice.is_empty() {
        return None;
    }

    // Initialize `largest` with the first element of the slice.
    let mut largest = slice[0];

    // Iterate over the rest of the elements (starting from the second element).
    for &element in slice.iter().skip(1) {
        if element > largest {
            largest = element;
        }
    }

    Some(largest)
}

