///
/// # Arguments
///
/// * `vec` - The input vector containing elements of type `T`.
///
/// # Returns
///
/// A new vector containing only the unique elements from the input vector.
pub fn remove_duplicates<T: Eq + std::hash::Hash>(vec: Vec<T>) -> Vec<T> {
    let set: HashSet<T> = vec.into_iter().collect();

    // Re-create the vector by iterating over the set
    set.into_iter().collect()
}

fn main() {
    let numbers = vec![1, 2, 2, 3, 4, 1, 5, 3];
    let unique_numbers = remove_duplicates(numbers);
    println!("Original: {:?}", numbers);
    println!("Unique:   {:?}", unique_numbers); // Output: [1, 2, 3, 4, 5] (Order might vary slightly depending on HashSet implementation, but generally preserves insertion order for modern Rust)

    let strings = vec!["apple", "banana", "apple", "cherry", "banana"];
    let unique_strings = remove_duplicates(strings);
    println!("Original: {:?}", strings);
    println!("Unique:   {:?}", unique_strings); // Output: ["apple", "banana", "cherry"]
}
```

**Explanation:**

1. **Trait Bounds (`T: Eq + std::hash::Hash`):** This is crucial. To store elements in a `HashSet`, the type `T` must implement two traits:
   * `Eq`: Allows comparison (`==`) between elements.
   * `std::hash::Hash`: Allows the element to be hashed, which is necessary for the `HashSet` to determine where to store it.
2. **`vec.into_iter().collect()`:** We consume the input vector and collect all its elements into a `HashSet`. Duplicates are automatically discarded during this collection process.
3. **`set.into_iter().collect()`:** We convert the resulting `HashSet` back into a `Vec<T>`.

