/// Computes the factorial of a non-negative integer n.
///
/// The factorial of n (n!) is the product of all positive integers less than or equal to n.
/// By definition, 0! is 1.
///
/// # Arguments
///
/// * `n` - The non-negative integer for which to compute the factorial.
///
/// # Returns
///
/// The factorial of n as a `u64`. Returns 1 if n is 0.
///
/// # Panics
///
/// This function will panic if `n` is negative, as the factorial is not defined for negative numbers
/// in this context.
pub fn factorial(n: u64) -> u64 {
    if n == 0 {
        return 1;
    }

    let mut result: u64 = 1;
    for i in 1..=n {
        // Note: For very large 'n' (n > 20 for u64), this will overflow.
        // If you need to handle larger numbers, you should use a BigInt library.
        result *= i;
    }
    result
}

fn main() {
    let num1: u64 = 5;
    let fact1 = factorial(num1);
    println!("The factorial of {} is: {}", num1, fact1); // Output: The factorial of 5 is: 120

    let num2: u64 = 0;
    let fact2 = factorial(num2);
    println!("The factorial of {} is: {}", num2, fact2); // Output: The factorial of 0 is: 1

    let num3: u64 = 10;
    let fact3 = factorial(num3);
    println!("The factorial of {} is: {}", num3, fact3); // Output: The factorial of 10 is: 3628800

    // Example of potential overflow (13! is too large for u64)
    let num4: u64 = 20;
    let fact4 = factorial(num4);
    println!("The factorial of {} is: {}", num4, fact4);
}
```

